  // Convert to array of arrays
  const rows = csvText
    .trim()
    .split("\n")
    .map((row) => row.split(","));

  // Filter rows where address (column index 3) contains 'CANTT'
  const filtered = rows.filter((row) =>
    row[3]?.toUpperCase().includes("TOWN SHIP")
  );

  // Initialize DataTable
  const dataTable = $("#dataTable").DataTable({
    dom: "Bfrtip",
    autoWidth: false,
    responsive: true,
    buttons: [
      {
        extend: "csvHtml5",
        text: "Export Filtered CSV",
        title: "Filtered_Records",
      },
    ],
  });

  // Add filtered rows to DataTable
  filtered.forEach((row) => dataTable.row.add(row));
  dataTable.draw();
